const response = $input.first().json;
if (response.error) throw new Error(`n8n API error: ${JSON.stringify(response.error)}`);
const workflows = response.data || [response];
if (!Array.isArray(workflows) || workflows.length === 0) throw new Error('No workflows returned.');
const apiKey = $node['Config'].json.n8nApiKey;
function slugify(name) {
  return (name || 'unnamed').toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').substring(0, 80);
}
const active = workflows.filter(wf => !wf.isArchived);
if (active.length === 0) throw new Error('No non-archived workflows found.');
return active.map(wf => ({ json: { workflowId: wf.id, workflowName: wf.name, active: wf.active, createdAt: wf.createdAt, updatedAt: wf.updatedAt, tags: wf.tags || [], folderSlug: slugify(wf.name), filePath: `workflows/${slugify(wf.name)}/workflow.json`, n8nApiKey: apiKey } }));

const items = $input.all();
const config = $node['Config'].json;

function slugify(name) {
  return (name || 'unnamed').toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '').substring(0, 80);
}

const SECRET_KEYS = new Set([
  'credentials','password','secret','token','apikey','api_key','apiKey',
  'n8nApiKey','githubToken','accessToken','access_token','refreshToken',
  'refresh_token','clientSecret','client_secret','privateKey','private_key',
  'webhook_secret','signing_secret','encryption_key','auth','authorization',
  'value','headerValue','queryValue','apiToken','apiSecret','bearerToken',
  'secretKey','connectionString','databaseUrl','webhookUrl','personalAccessToken',
  'oauthToken','oauthSecret','passphrase','serviceAccountKey','key'
]);

function looksLikeSecret(str) {
  if (typeof str !== 'string') return false;
  const s = str.trim();
  if (s.length < 16) return false;
  if (/^(eyJ|ghp_|gho_|ghu_|ghs_|ghr_|github_pat_|sk-|sk_|xox[bprs]-|glpat-|Bearer |Basic |AKIA|AIza|SG\.|ntn_|secret_|whsec_|rk_live_|rk_test_|pk_live_|pk_test_|sq0[a-z]{3}-|sk_live_|sk_test_|shpat_|shpss_|shppa_)/.test(s)) return true;
  if (/^[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}$/.test(s)) return true;
  if (/^[A-Za-z0-9_\-]{30,}$/.test(s)) return true;
  if (/^[A-Za-z0-9+\/=]{40,}$/.test(s)) return true;
  if (/[0-9a-f]{32,}/i.test(s) && s.length < 200) return true;
  return false;
}

function sanitize(obj, parentKey, depth) {
  if (depth > 50) return obj;
  if (obj === null || obj === undefined) return obj;
  if (typeof obj === 'string') {
    const keyLower = (parentKey || '').toLowerCase();
    if (SECRET_KEYS.has(parentKey) && obj.length > 8) return '[REDACTED]';
    if (obj.length > 8 && /secret|token|password|apikey|api_key|bearer|auth_|credential/i.test(keyLower)) return '[REDACTED]';
    if (looksLikeSecret(obj)) return '[REDACTED]';
    return obj;
  }
  if (Array.isArray(obj)) return obj.map(v => sanitize(v, parentKey, depth + 1));
  if (typeof obj !== 'object') return obj;
  const clean = {};
  for (const [k, val] of Object.entries(obj)) {
    if (k === 'credentials') { clean[k] = {}; continue; }
    if (k === 'shared') { clean[k] = []; continue; }
    if (k === 'staticData' && val) { clean[k] = null; continue; }
    clean[k] = sanitize(val, k, depth + 1);
  }
  return clean;
}

const tree = [];
const indexWorkflows = [];

for (const item of items) {
  const wf = item.json;
  if (wf.error) continue;
  const name = wf.name || 'unnamed';
  const slug = slugify(name);
  const filePath = `workflows/${slug}/workflow.json`;
  const sanitized = sanitize(wf, null, 0);
  tree.push({ path: filePath, mode: '100644', type: 'blob', content: JSON.stringify(sanitized, null, 2) });
  indexWorkflows.push({ workflowId: wf.id, workflowName: name, active: wf.active, folder: `workflows/${slug}`, file: filePath });
}

const index = {
  generatedAt: new Date().toISOString(),
  source: 'n8n automated weekly backup',
  workflowCount: indexWorkflows.length,
  workflows: indexWorkflows
};
tree.push({ path: 'published-workflows-index.json', mode: '100644', type: 'blob', content: JSON.stringify(index, null, 2) });

return [{ json: { tree, owner: config.owner, repo: config.repo, branch: config.branch, githubToken: config.githubToken, workflowCount: indexWorkflows.length } }];

